command:
set +e; STATE=/home/andreas/.gstack/browse.json; echo STATE_EXISTS=$([ -f "$STATE" ] && echo yes || echo no); PID=$(python3 - <<'PY'
import json,os
p=os.path.expanduser('~/.gstack/browse.json')
try: print(int(json.load(open(p)).get('pid') or 0))
except Exception: print(0)
PY
); echo GSTACK_SERVER_PID=$PID; if [ "$PID" -gt 1 ] 2>/dev/null; then echo TREE_BEFORE; pstree -ap "$PID" 2>/dev/null | head -40; kill "$PID" 2>/dev/null || true; sleep 2; kill -9 "$PID" 2>/dev/null || true; fi; rm -f "$STATE"; echo SERVER_ALIVE=$([ "$PID" -gt 1 ] 2>/dev/null && kill -0 "$PID" 2>/dev/null && echo yes || echo no); echo HUMAN_BRAVE; pgrep -af '^/opt/brave.com/brave/brave --restore-last-session$|/usr/bin/brave-browser --restore-last-session' | head -10; echo QUARANTINED_NO_BROWSER_COMMANDS_RUN
